import{_ as o,a0 as l,w as p,s as d,ao as r,I as t,x as s,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何更新 Linux 的符號鏈接 | LCTT x X-CMD","titleTemplate":false,"description":"如何更新 Linux 的符號鏈接 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何更新 Linux 的符號鏈接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何更新 Linux 的符號鏈接 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211104 How to update a Linux symlink","title":"如何更新 Linux 的符號鏈接","tag":"202111","desc":""},"relativePath":"202111/20211104 How to update a Linux symlink.md","filePath":"[post].md"}'),c={name:"202111/20211104 How to update a Linux symlink.md"};function u(g,e,h,k,f,m){const n=l("Link");return p(),d("div",null,[e[15]||(e[15]=r(`<h1 id="如何更新-linux-的符號鏈接" tabindex="-1">如何更新 Linux 的符號鏈接 <a class="header-anchor" href="#如何更新-linux-的符號鏈接" aria-label="Permalink to “如何更新 Linux 的符號鏈接”">​</a></h1><blockquote><p>鏈接一直是 UNIX 文件系統的一個獨特的高級功能。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/13/185626ubb832pphjhlpmly.jpg" alt=""></p><p>UNIX 和 Linux 用户發現鏈接有很多用途，特別是符號鏈接。我喜歡使用符號鏈接的一種方式是管理各種 IT 設備的配置備份。</p><p>我有一個目錄結構，用來存放我的文檔、更新及網絡上其他和計算機和設備有關的文件。設備可以包括路由器、接入點、NAS 服務器和筆記本電腦，通常有不同的品牌和版本。配置備份本身可能在目錄樹的深處，例如 <code>/home/alan/Documents/network/device/NetgearRL5000/config</code>。</p><p>為了簡化備份過程，我在主目錄中有一個名為 <code>Configuration</code> 的目錄。我使用這個目錄的符號鏈接來指向特定的設備目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:~/Configuration/ $ ls -F1</span></span>
<span class="line"><span>Router@</span></span>
<span class="line"><span>Accesspoint@</span></span>
<span class="line"><span>NAS@</span></span></code></pre></div><p><strong>注意</strong>：<code>ls</code> 命令的 <code>-F</code> 選項在每個文件名上附加特殊字符以表示其類型。如上所示，<code>@</code> 符號表示這些是鏈接。</p><h3 id="創建一個鏈接" tabindex="-1">創建一個鏈接 <a class="header-anchor" href="#創建一個鏈接" aria-label="Permalink to “創建一個鏈接”">​</a></h3><p>符號鏈接 <code>Router</code> 指向我的 Netgear RL5000 的 <code>config</code> 目錄。創建它的命令是 <code>ln -s</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ln -s /home/alan/Documents/network/device/NetgearRL5000/config Router</span></span></code></pre></div><p>然後，用 <code>ls -l</code> 看一下並確認：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:~/Configuration/ $ ls -l</span></span>
<span class="line"><span>Router -&gt; /home/alan/Documents/network/device/NetgearRL5000/config</span></span>
<span class="line"><span>NAS -&gt; /home/alan/Documents/network/device/NFSBox/config</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>這樣做的好處是，當對這個設備進行維護時，我只需進入 <code>~/Configuration/Router</code>。</p><p>如果我決定用一個新的型號替換這個路由器，使用符號鏈接的第二個好處就很明顯了。我可能會把舊的路由器改成一個接入點。因此，它的目錄並沒有被刪除。相反，我有一個新的目錄，對應於新的路由器，也許是華碩 DF-3760。我創建這個目錄並確認它的存在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p ~/Documents/network/device/ASUSDF-3760/config</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:~/Documents/network/device/ $ ls</span></span>
<span class="line"><span>NetgearRL5000</span></span>
<span class="line"><span>ASUSDF-3760</span></span>
<span class="line"><span>NFSBox</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>另一個例子是，如果你的辦公室裏有幾個接入點。你可以使用符號鏈接在邏輯上代表每一個，用一個通用的名字，如 <code>ap1</code>，<code>ap2</code>，等等，或者你可以使用描述性的詞語，如 <code>ap_floor2</code>，<code>ap_floor3</code>，等等。這樣，當物理設備隨時間變化時，你不必持續更新任何可能管理它們的進程，因為它們是在處理鏈接而不是實際的設備目錄。</p><h3 id="更新一個鏈接" tabindex="-1">更新一個鏈接 <a class="header-anchor" href="#更新一個鏈接" aria-label="Permalink to “更新一個鏈接”">​</a></h3><p>由於我的主路由器已經改變，我想讓路由器的符號鏈接指向它的目錄。我可以使用 <code>rm</code> 和 <code>ln</code> 命令來刪除和創建一個新的符號鏈接，但是有一種方法可以只用 <code>ln</code> 命令和幾個選項就可以一步完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:~/Configuration/ $ ln -vfns ~/Documents/network/device/ASUSDF-3760/config/ Router</span></span>
<span class="line"><span>&#39;Router&#39; -&gt; &#39;/home/alan/Documents/network/device/ASUSDF-3760/config/&#39;</span></span>
<span class="line"><span>:~/Configuration/ $ ls -l</span></span>
<span class="line"><span>Router -&gt; /home/alan/Documents/network/device/ASUSDF-3760/config</span></span>
<span class="line"><span>NAS -&gt; /home/alan/Documents/network/device/NFSBox/config</span></span></code></pre></div><p>根據手冊頁，這些選項如下：</p><ul><li><code>-v</code>、<code>--verbose</code>：打印每個鏈接文件的名稱</li><li><code>-f</code>、<code>--force</code>：刪除目標文件（有必要，因為已經存在一個鏈接）</li><li><code>-n</code>、<code>--no-dereference</code>：如果鏈接名是一個目錄的符號鏈接，就把它當作一個正常的文件</li><li><code>-s</code>、<code>--symbolic</code>：製作符號鏈接而不是硬鏈接</li></ul><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>鏈接是 UNIX 和 Linux 文件系統中最強大的功能之一。其他操作系統也曾試圖模仿這種能力，但由於他們的文件系統缺乏基本的鏈接設計，這些系統從來沒有工作得那麼好，也沒有那麼可用。</p><p>上面的演示只是利用鏈接在生活生產環境中無縫瀏覽不斷變化的目錄結構的眾多可能性中的一種。鏈接提供了一個永遠不會長期靜態的組織所需的靈活性。</p><hr>`,27)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),a(n,{href:"https://opensource.com/article/21/11/update-linux-file-system-link"},{default:i(()=>[...e[0]||(e[0]=[s("https://opensource.com/article/21/11/update-linux-file-system-link",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),a(n,{href:"https://opensource.com/users/alanfdoss"},{default:i(()=>[...e[2]||(e[2]=[s("Alan Formy-Duval",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const v=o(c,[["render",u]]);export{C as __pageData,v as default};
